  if (select (md5(prompt) = 'd49ca9dc7f161bcab92750419be2ec3a' and md5(dataset) = 'eb502fb41727b21f5d142446e9bc9d5c' and fields = '[{"key": "lab_j_per_psi", "tol": 0.0001, "unit": "1/psi", "label": "Ahmed 4-7 lab J factor per psi", "expected": 0.0967993827459659}, {"key": "j_at_sw02", "tol": 0.0005, "unit": "-", "label": "Ahmed 4-7 J at Sw 0.20 (full precision)", "expected": 0.16939891980544033}, {"key": "res_pc_sw02", "tol": 0.002, "unit": "psi", "label": "Reservoir Pc at Sw 0.20 from the printed J", "expected": 1.5534071373580902}, {"key": "h_entry_m", "tol": 0.01, "unit": "m", "label": "Ekene entry height above the FWL", "expected": 3.142982863763458}, {"key": "fwl_m", "tol": 0.02, "unit": "m TVD", "label": "Ekene free water level", "expected": 1563.1429828637636}, {"key": "sw_at_crest", "tol": 0.0005, "unit": "fraction", "label": "Water saturation at the crest", "expected": 0.35062979402484734}]'::jsonb) from public.academy_capstones where app_slug = 'scal' and tier = 'intermediate' and active) is not true then
