  if (select (md5(prompt) = '2f1bd16e772b7aab505fc5a0f04d4c6d' and md5(dataset) = '208f2b7f16c70a41dbcd488ea2f6b7f8' and fields = '[{"key": "fitted_nw_printed_grid", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw, kr printed to 3 dp", "expected": 2.4318603318221883}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb) from public.academy_capstones where app_slug = 'scal' and tier = 'advanced' and active) is not true then
